const rulers=[{id:"iltutmish",name:"Iltutmish",reign:"1211 – 1236 CE",metal:"silver",denom:"Tanka",script:"Arabic",obverseText:"Al-Sultan",reverseText:"Iltutmish",arabic:"السلطان الأعظم",translit:"Al-Sultan Al-Azam",translation:"The Supreme Sultan",mints:[{name:"Delhi",x:200,y:100},{name:"Lahore",x:150,y:60}],context:"Introduced the silver Tanka and copper Jital, which became the standard coinage of the Sultanate.",color:"#e6e6e6"},{id:"balban",name:"Ghiyas ud din Balban",reign:"1266 – 1287 CE",metal:"silver",denom:"Tanka",script:"Arabic, Nagari",obverseText:"Balban",reverseText:"Sultan",arabic:"غياث الدنيا والدين",translit:"Ghiyas ud-Dunya wa ud-Din",translation:"The Helper of the World and Religion",mints:[{name:"Delhi",x:200,y:100}],context:"Maintained the monetary standard of Iltutmish; bilingual coins with Nagari script were common for local acceptance.",color:"#e6e6e6"},{id:"alauddin",name:"Alauddin Khalji",reign:"1296 – 1316 CE",metal:"gold",denom:"Gold Tanka",script:"Arabic",obverseText:"Sikandar",reverseText:"Al-Sani",arabic:"سكندر الثاني",translit:"Sikandar al-Sani",translation:"The Second Alexander",mints:[{name:"Delhi",x:200,y:100},{name:"Deogir",x:180,y:180}],context:"Enriched the treasury via Deccan campaigns, leading to an abundance of gold Tankas. Coins proclaimed him the Second Alexander.",color:"#d4af37"},{id:"muhammad",name:"Muhammad bin Tughlaq",reign:"1324 – 1351 CE",metal:"copper",denom:"Token Currency (Tanka)",script:"Arabic",obverseText:"Token",reverseText:"Tughlaq",arabic:"من أطاع السلطان فقد أطاع الرحمن",translit:"Man ata'a al-Sultan faqad ata'a al-Rahman",translation:"He who obeys the Sultan obeys the Merciful",mints:[{name:"Delhi",x:200,y:100},{name:"Daulatabad",x:180,y:180}],context:"Famous for his failed experiment introducing copper and brass token currency intended to pass at the value of silver.",color:"#b87333"}];function initCarousel(){const e=document.getElementById("ruler-carousel");rulers.forEach(t=>{const n=document.createElement("div");n.className=`ruler-card metal-${t.metal}`,n.dataset.id=t.id,n.innerHTML=`<div class="ruler-name">${t.name}</div><div class="ruler-dates">${t.reign}</div>`,n.addEventListener("click",()=>{document.querySelectorAll(".ruler-card").forEach(e=>e.classList.remove("selected")),n.classList.add("selected"),selectRuler(t)}),e.appendChild(n)}),e.firstChild.classList.add("selected")}function initFilters(){const e=document.querySelectorAll(".filter-btn");e.forEach(t=>{t.addEventListener("click",()=>{e.forEach(e=>e.classList.remove("active")),t.classList.add("active");const n=t.dataset.metal;document.querySelectorAll(".ruler-card").forEach(e=>{"all"===n||e.classList.contains(`metal-${n}`)?e.style.display="block":e.style.display="none"})})})}function selectRuler(e){document.getElementById("det-ruler").textContent=e.name,document.getElementById("det-reign").textContent=e.reign,document.getElementById("det-denom").textContent=e.denom,document.getElementById("det-metal").textContent=e.metal.charAt(0).toUpperCase()+e.metal.slice(1),document.getElementById("det-script").textContent=e.script;document.querySelectorAll(".coin-svg circle").forEach(t=>t.setAttribute("fill",e.color)),document.getElementById("svg-obverse-text").textContent=e.obverseText,document.getElementById("svg-reverse-text").textContent=e.reverseText,document.getElementById("decoder-arabic").textContent=e.arabic,document.getElementById("decoder-translit").textContent=e.translit,document.getElementById("decoder-translation").textContent=`"${e.translation}"`;const t=document.getElementById("mint-nodes");t.innerHTML="";const n=[];e.mints.forEach(e=>{n.push(e.name),t.innerHTML+=`\n            <circle cx="${e.x}" cy="${e.y}" r="5" class="mint-node"></circle>\n            <text x="${e.x+10}" y="${e.y+5}" class="mint-label">${e.name}</text>\n        `}),document.getElementById("mint-desc").innerHTML=`<strong>Active Mints:</strong> ${n.join(", ")}<br><br>${e.context}`}function initCompare(){const e=document.getElementById("compare-1"),t=document.getElementById("compare-2");rulers.forEach(n=>{e.add(new Option(n.name,n.id)),t.add(new Option(n.name,n.id))}),rulers.length>1&&(t.selectedIndex=1);const n=(e,t)=>{const n=rulers.find(t=>t.id===e.value);n&&(document.getElementById(t).innerHTML=`\n                <p><strong>Reign:</strong> ${n.reign}</p>\n                <p><strong>Metal:</strong> <span style="color:${n.color}">${n.metal.toUpperCase()}</span></p>\n                <p><strong>Denomination:</strong> ${n.denom}</p>\n            `)};e.addEventListener("change",()=>n(e,"compare-stats-1")),t.addEventListener("change",()=>n(t,"compare-stats-2")),n(e,"compare-stats-1"),n(t,"compare-stats-2")}document.addEventListener("DOMContentLoaded",()=>{initCarousel(),initFilters(),initCompare(),selectRuler(rulers[0])});